// Presentation and dated workflow for the interactive demo. No external services.
let demoClock=new Date('2026-10-06T10:30:00+08:00'),homeFilter='all',documentIndex=0,fromDate='',untilDate='';
const dayKey=d=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Manila',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(d));
const dateText=d=>d?new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Manila',day:'numeric',month:'short',year:'numeric'}).format(new Date(d.length===10?d+'T12:00:00+08:00':d)):'Not yet';
const timeText=d=>d?new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Manila',day:'numeric',month:'short',year:'numeric',hour:'numeric',minute:'2-digit',hour12:true}).format(new Date(d)):'Not yet';
const nowStamp=()=>demoClock.toISOString();function tick(){demoClock=new Date(demoClock.getTime()+60000);return nowStamp();}function addDays(days){const d=new Date(demoClock);d.setDate(d.getDate()+days);return dayKey(d);}function isDue(r){return !!r.followupDate&&r.followupDate<=dayKey(demoClock)&&!['Paid','Denied'].includes(r.status);}
const statusName=s=>({'Lacking':'Missing documents','Submitted':'Sent · awaiting reply','Processing':'Under review','Approved':'Approved · unpaid'}[s]||s);
const baseMake=makeRecord,baseSeed=seed,baseBadge=badge,baseRender=render,baseOverview=overview,baseComposer=composer,baseSend=sendEmail,baseReply=simulateReply,baseStatusDialog=statusDialog,baseSaveStatus=saveStatus,baseConfirm=confirmProposal;
makeRecord=function(...args){const r=baseMake(...args);Object.assign(r,{submittedAt:nowStamp(),updatedAt:nowStamp(),sentAt:null,replyAt:null,paidAt:null,followupDate:null});r.events=r.events.map(text=>({text,at:nowStamp()}));return r;};
function seedDates(){const days=[6,5,3,2,1,1];records.forEach((r,i)=>{r.submittedAt=`2026-10-${String(days[i]).padStart(2,'0')}T09:00:00+08:00`;r.updatedAt=r.submittedAt;r.followupDate=r.followup?(i===3?'2026-10-05':'2026-10-08'):null;r.sentAt=['Processing','Paid'].includes(r.status)?`2026-10-02T09:32:00+08:00`:null;r.replyAt=i===4?'2026-10-05T10:24:00+08:00':null;r.paidAt=r.status==='Paid'?'2026-10-05':null;r.updatedAt=r.replyAt||r.sentAt||r.submittedAt;if(r.paidAt)r.updatedAt='2026-10-05T14:00:00+08:00';r.events=[{text:'Request received from the sample Form.',at:r.submittedAt}];if(r.sentAt)r.events.unshift({text:'Supporting documents emailed to AMAPHIL.',at:r.sentAt});if(r.replyAt)r.events.unshift({text:'Reply received from AMAPHIL.',at:r.replyAt});if(r.paidAt)r.events.unshift({text:'Payment recorded.',at:r.updatedAt});});messages.forEach((m,i)=>m.at=['2026-10-02T09:32:00+08:00','2026-10-05T10:24:00+08:00','2026-10-06T08:10:00+08:00'][i]);}
seed=function(){demoClock=new Date('2026-10-06T10:30:00+08:00');baseSeed();seedDates();homeFilter='all';documentIndex=0;};seedDates();
log=function(r,text){r.updatedAt=tick();r.events.unshift({text,at:r.updatedAt});};
badge=function(s){return baseBadge(s).replace(esc(s)+'</span>',esc(statusName(s))+'</span>');};
attention=function(r){if(['Paid','Denied'].includes(r.status))return null;if(r.proposal)return {label:'Decision to review',kind:'decision',tab:'Emails',action:'Read reply',help:'Read the department’s decision and confirm the correct status.'};if(unreadReply(r))return {label:'New reply',kind:'reply',tab:'Emails',action:'Read reply',help:'A department has replied. Read the message before deciding what to do.'};if(r.status==='Lacking')return {label:'Missing documents',kind:'missing',tab:'Requirements',action:'Check missing files',help:'Identify the missing or unclear files and request a replacement.'};if(r.status==='New request')return {label:r.docs.every(d=>d.reviewed&&!d.replace)?'Ready to email':'Documents need checking',kind:'new',tab:'Documents',action:r.docs.every(d=>d.reviewed&&!d.replace)?'Prepare email':'Check documents',help:'Open each file and check that it is readable and belongs to this request.'};if(isDue(r))return {label:r.followupDate<dayKey(demoClock)?'Follow-up overdue':'Follow-up due today',kind:'followup',tab:'Emails',action:'Send follow-up',help:'No update has been recorded. Review the conversation and send a reminder.'};if(r.status==='Approved')return {label:'Waiting for payment',kind:'payment',tab:'Overview',action:'View payment details',help:'Record payment only after receiving confirmation.'};return null;};
function act(id){const r=records.find(x=>x.id===id),a=attention(r);current=id;documentIndex=0;if(a?.kind==='followup'){startCompose('followup');loadTemplate('followup');}else if(a?.kind==='new'&&r.docs.every(d=>d.reviewed&&!d.replace)){startCompose();}else openRecord(id,a?.tab||'Overview');}
function dueText(r){if(!r.followupDate)return 'Not scheduled';const overdue=r.followupDate<dayKey(demoClock);return dateText(r.followupDate)+(overdue?' · Overdue':r.followupDate===dayKey(demoClock)?' · Today':'');}
function dateBar(r){return `<div class="datebar"><div><span>Received</span>${dateText(r.submittedAt)}</div><div><span>Last updated</span>${timeText(r.updatedAt)}</div><div><span>Email sent</span>${r.sentAt?dateText(r.sentAt):'Not sent yet'}</div><div><span>Follow up on</span><strong class="${isDue(r)?'overdue':''}">${dueText(r)}</strong></div></div>`;}
function taskCard(r){const a=attention(r);return `<article class="workcard ${r.status==='New request'?'new':''}"><div><h3>${esc(r.name)}</h3><div class="ref">${r.id}</div><div class="metadata">${badge(r.status)}<span>${money(r.amount)}</span></div></div><div><dl class="datepair"><dt>Received</dt><dd>${dateText(r.submittedAt)}</dd><dt>${a?.kind==='followup'?'Follow up':'Updated'}</dt><dd class="${a?.kind==='followup'?'overdue':''}">${a?.kind==='followup'?dueText(r):dateText(r.updatedAt)}</dd></dl><p class="reason">${esc(a?.label||'No action needed')}</p></div>${btn(a?.action||'Open request',`act('${r.id}')`,'primary actionbutton')}</article>`;}
dashboard=function(){const tasks=records.filter(r=>attention(r)&&attention(r).kind!=='payment');const kinds=[['all','All to do'],['new','Check documents'],['reply','Read replies'],['followup','Follow up']];const match=(r,k)=>k==='all'||(k==='reply'?['reply','decision'].includes(attention(r)?.kind):attention(r)?.kind===k);const shown=tasks.filter(r=>match(r,homeFilter)).sort((a,b)=>(isDue(b)?1:0)-(isDue(a)?1:0));return `<div class="homeintro"><div><h1>What needs to be done?</h1><p>Choose a request below. Each button opens the next step for that request.</p></div><div class="todaybox"><strong>${dateText(nowStamp())}</strong><small>Demo date · Philippine time</small></div></div><div class="taskfilters">${kinds.map(([k,label])=>`<button class="taskfilter ${homeFilter===k?'active':''}" data-kind="${k}" aria-pressed="${homeFilter===k}" onclick="homeFilter='${k}';render()"><strong>${tasks.filter(r=>match(r,k)).length}</strong><div>${label}<small>${k==='all'?'Requests needing action':k==='new'?'Review the uploaded files':k==='reply'?'Check the latest response':'Reminders due or overdue'}</small></div></button>`).join('')}</div><div class="sectionhead"><h2>${homeFilter==='all'?'Your next tasks':kinds.find(x=>x[0]===homeFilter)[1]}</h2>${btn('See all requests',"go('Reimbursements')")}</div><div class="workcards">${shown.map(taskCard).join('')||'<div class="panel empty">Nothing to do in this category. You can check all requests or try a sample submission.</div>'}</div><details class="helpdetails"><summary>How does a request move through the system?</summary><div class="howsteps"><div><span class="stepnum">1</span>Check documents</div><div><span class="stepnum">2</span>Send email</div><div><span class="stepnum">3</span>Read the reply</div><div><span class="stepnum">4</span>Record the outcome</div></div><p>The app gathers the information. You review the files, choose what to send, and confirm decisions.</p></details><div class="sectionhead"><div><h3>Try the full process</h3><p class="hint">Add a fictional request with four sample files.</p></div>${btn('Add sample request',"page='Form';render()")}</div>`;};
table=function(rows){return `<div class="tablewrap"><table><thead><tr><th>Client / reference</th><th>Received</th><th>Status</th><th>Next step / date</th><th></th></tr></thead><tbody>${rows.map(r=>{const a=attention(r);return `<tr class="${r.status==='New request'?'new-request-row':''}"><td data-label="Client"><strong>${esc(r.name)}</strong><small>${r.id} · ${money(r.amount)}</small></td><td data-label="Received" class="datecell">${dateText(r.submittedAt)}<small>Updated ${dateText(r.updatedAt)}</small></td><td data-label="Status">${badge(r.status)}</td><td data-label="Next step">${esc(a?.label||'No action needed')}<small class="${isDue(r)?'overdue':''}">${r.followupDate?'Follow up '+dueText(r):r.paidAt?'Paid '+dateText(r.paidAt):r.sentAt?'Sent '+dateText(r.sentAt):'Not emailed yet'}</small></td><td>${btn('Open request',`openRecord('${r.id}')`)}</td></tr>`;}).join('')||'<tr><td colspan="5" class="empty">No requests match your search.</td></tr>'}</tbody></table></div>`;};
function filteredRequests(term=''){return records.filter(r=>matchesFilter(r)&&(r.name+' '+r.id).toLowerCase().includes(term.toLowerCase())&&(!fromDate||dayKey(r.submittedAt)>=fromDate)&&(!untilDate||dayKey(r.submittedAt)<=untilDate));}
list=function(){return heading('All requests','Find a reimbursement by client, reference, status, or received date.',btn('Add sample request',"page='Form';render()"))+`<div class="filters"><input id="search" aria-label="Search requests" placeholder="Search client name or reference" oninput="searchRows(this.value)"><select aria-label="Status" onchange="filter=this.value;searchRows(document.querySelector('#search').value)">${['All','Needs attention','New request','Lacking','Submitted','Processing','Approved','Paid','Denied'].map(s=>`<option value="${s}" ${s===filter?'selected':''}>${s==='All'?'All statuses':statusName(s)}</option>`).join('')}</select></div><div class="filterdates"><label>Received from<input type="date" value="${fromDate}" onchange="fromDate=this.value;searchRows(document.querySelector('#search').value)"></label><label>Received through<input type="date" value="${untilDate}" onchange="untilDate=this.value;searchRows(document.querySelector('#search').value)"></label>${btn('Clear filters',"fromDate='';untilDate='';filter='All';render()")}${btn('Download list','exportCsv()')}</div><div id="dateerror" class="danger" role="alert"></div><div class="panel flush" id="result">${table(filteredRequests())}</div>`;};
searchRows=function(s){$('#dateerror').textContent=fromDate&&untilDate&&fromDate>untilDate?'The start date must be before the end date.':'';$('#result').innerHTML=table(filteredRequests(s));};
detail=function(){const r=rec(),a=attention(r);return `<div class="heading"><div><div class="recordtitle"><h1>${esc(r.name)}</h1>${badge(r.status)}</div><p class="recordsub">${r.id} · AMAPHIL · ${money(r.amount)}</p></div>${btn('Back to requests',"current=null;render()")}</div>${dateBar(r)}${a?`<div class="nextstep"><div><div class="label">NEXT STEP</div><h3>${a.label}</h3><p>${a.help}</p></div>${btn(a.action,`act('${r.id}')`,'primary')}</div>`:`<div class="note">${r.status==='Paid'?'Payment recorded on '+dateText(r.paidAt)+'. No further action is needed.':r.status==='Denied'?'This request was denied. See the history for the reason.':'Waiting for a reply. '+(r.followupDate?'Your next follow-up is '+dateText(r.followupDate)+'.':'You can set a follow-up date in Emails.')}</div>`}<div class="tabs">${[['Overview','Details'],['Documents','Documents'],['Requirements','Checklist'],['Emails','Emails'],['History','History']].map(([key,label])=>btn(label,`setTab('${key}')`,tab===key?'active':'')).join('')}</div>${tab==='Overview'?overview(r):tab==='Documents'?documents(r):tab==='Requirements'?checklist(r):tab==='Emails'?caseEmails(r):history(r)}`;};
overview=function(r){return `<div class="twocol recordfacts"><section class="panel"><h3>Client and reimbursement</h3><dl class="kv"><dt>Client</dt><dd>${esc(r.name)}</dd><dt>Email</dt><dd>${esc(r.email)}</dd><dt>Date of treatment</dt><dd>${dateText(r.date)}</dd><dt>Facility</dt><dd>${esc(r.facility)}</dd><dt>Amount requested</dt><dd>${money(r.amount)}</dd><dt>Amount approved</dt><dd>${r.approved?money(r.approved):'Not confirmed'}</dd><dt>Payment date</dt><dd>${r.paidAt?dateText(r.paidAt):'Not recorded'}</dd></dl></section><section class="panel"><h3>Notes and outcome</h3>${r.notes.map(n=>`<p>${esc(n)}</p>`).join('')||'<p class="muted">Use notes for information the other staff member needs to know.</p>'}<div class="actions">${btn('Add a note','noteDialog()')}${btn('Update status','statusDialog()')}</div><details class="helpdetails"><summary>What do the statuses mean?</summary><p><strong>New request:</strong> not yet sent. <strong>Missing documents:</strong> files need to be completed. <strong>Sent:</strong> waiting for acknowledgement. <strong>Under review:</strong> the department is processing it. <strong>Approved:</strong> payment is still pending. <strong>Paid:</strong> payment has been confirmed.</p></details></section></div>`;};
documents=function(r){documentIndex=Math.min(documentIndex,r.docs.length-1);const d=r.docs[documentIndex],checked=r.docs.filter(d=>d.reviewed&&!d.replace).length,selected=r.docs.filter(d=>d.selected).length,allReady=checked===r.docs.length&&selected>0;return `<div class="sectionhead"><div><h2>1. Check the documents</h2><p class="hint">Open each file. Check readability and client details, then mark it checked.</p></div><strong>${checked} of ${r.docs.length} checked</strong></div><div class="reviewlayout"><div class="filelist" aria-label="Supporting files">${r.docs.map((d,i)=>`<button class="filebutton ${i===documentIndex?'active':''}" aria-pressed="${i===documentIndex}" onclick="documentIndex=${i};render()"><strong>${i+1}. ${esc(d.name)}</strong><small>${d.replace?'Replacement needed':d.reviewed?'✓ Checked':'Not checked yet'} · ${d.size} MB</small></button>`).join('')}</div><section><div class="reviewpane"><div class="row between" style="margin-bottom:18px"><h3>${esc(d.name)}</h3>${btn('Enlarge preview',"document.querySelector('.reviewpane .paper').classList.toggle('enlarged')")}</div>${paper(d)}<div class="actions">${btn('File is clear — mark checked',`checkInline(${documentIndex})`,'primary')}${btn(d.replace?'Receive sample replacement':'File needs replacement',d.replace?`replaceDoc(${documentIndex})`:`flagInline(${documentIndex})`)}</div></div><div class="reviewchoice"><label class="check"><input type="checkbox" ${d.selected?'checked':''} ${d.replace?'disabled':''} onchange="selectDoc(${documentIndex},this.checked);render()">Include this file in the email</label><p class="hint" style="margin:7px 0 0">Checking a file confirms its quality. This checkbox controls whether it is sent.</p></div></section></div><div class="reviewfooter"><p>${allReady?'All required files are checked. You can prepare the email.':`${r.docs.length-checked} file(s) still need checking or replacement.`}<br><span class="hint">${selected} attachment(s) selected</span></p><button class="primary" onclick="startCompose()" ${!allReady?'disabled':''}>2. Prepare email</button></div>`;};
function checkInline(i){const r=rec(),d=r.docs[i];d.reviewed=true;d.replace=false;log(r,user+' checked '+d.name+'.');const next=r.docs.findIndex((d,j)=>j>i&&!d.reviewed);if(next>=0)documentIndex=next;render();notify(next>=0?'File checked. The next file is now open.':'File checked. Review the remaining files or prepare the email.');}function flagInline(i){const r=rec(),d=r.docs[i];d.replace=true;d.reviewed=false;d.selected=false;r.status='Lacking';log(r,'Replacement needed: '+d.name);render();}
checklist=function(r){return `<section class="panel"><h2>What is still needed?</h2><p class="hint">Files must be readable and checked before the first reimbursement email is sent.</p>${r.docs.map((d,i)=>`<div class="requirementsrow"><div><strong>${esc(d.name)}</strong><p>${d.replace?'Ask for a clearer or corrected copy.':d.reviewed?'Checked and ready.':'Received, but not checked yet.'}</p></div><div class="row">${badge(d.replace?'Needs replacement':d.reviewed?'Verified':'Needs review')}${btn('Open file',`documentIndex=${i};setTab('Documents')`)}</div></div>`).join('')}<div class="actions">${btn('Email a request for missing files',"startCompose('requirements')",'primary')}</div></section>`;};
history=function(r){return `<section class="panel"><h2>What happened and when</h2><p class="hint">Dates and times are shown in Philippine time.</p>${r.events.map(e=>`<div class="event"><time datetime="${esc(e.at)}">${timeText(e.at)}</time>${esc(e.text)}</div>`).join('')}</section>`;};
composer=function(){return baseComposer().replace('Compose email','2. Review and send the email').replace('Review the message and attachments before sending.','Check the recipient, message, and selected files. Nothing is sent until you press Send demo email.').replace('Simulate send','Send demo email').replaceAll('Inspect','View file').replace('<div class="note">Sending as','<div class="note">From:').replace('Simulated Gmail account','Demo mailbox · no real message will be sent');};
sendEmail=function(){const r=rec(),ok=baseSend();if(ok){r.sentAt=tick();r.updatedAt=r.sentAt;r.followupDate=addDays(3);messages[0].at=r.sentAt;render();notify('Demo email recorded. Follow up on '+dateText(r.followupDate)+' if there is no reply.');}return ok;};
simulateReply=function(){const r=rec();baseReply();r.replyAt=tick();r.updatedAt=r.replyAt;messages[0].at=r.replyAt;r.followup=false;r.followupDate=null;render();};
confirmProposal=function(){const r=rec();baseConfirm();r.followupDate=null;r.followup=false;render();};
messageHTML=function(m){return `<article class="email"><div class="emailhead"><strong>${esc(m.subject)}</strong>${badge(m.direction)}</div><small>${m.at?timeText(m.at):esc(m.date)} · Philippine time<br>From: ${esc(m.from)}<br>To: ${esc(m.to)}<br>${esc(m.owner)}’s demo mailbox</small><p>${esc(m.body)}</p>${m.files.map(f=>`<span class="attachment">${esc(f)}</span>`).join('')}</article>`;};
caseEmails=function(r){messages.filter(m=>m.caseId===r.id&&m.direction==='Inbox').forEach(m=>m.read=true);return `<div class="sectionhead"><div><h2>Email conversation</h2><p class="hint">Read the latest reply before changing the reimbursement status.</p></div><div class="row">${btn('Write an email','startCompose()')}${btn('Set follow-up date','followup()')}</div></div>${r.proposal?`<div class="nextstep"><div><div class="label">DECISION NEEDS YOUR CONFIRMATION</div><h3>${statusName(r.proposal.status)}</h3><p>Read the department’s reply below, then confirm or dismiss this suggestion.</p></div><div class="row">${btn('Confirm decision','confirmProposal()','primary')}${btn('Dismiss',"rec().proposal=null;render()")}</div></div>`:''}${messages.filter(m=>m.caseId===r.id).sort((a,b)=>(b.at||'').localeCompare(a.at||'')).map(messageHTML).join('')||'<div class="panel empty">No email has been sent for this request. Check the documents first.</div>'}<details class="helpdetails"><summary>Try a sample department reply</summary><p>Create a fictional acknowledgement, approval, missing-document request, or denial.</p>${btn('Add sample reply','replyDialog()')}</details>`;};
followup=function(){const r=rec();modal(modalHead('When should you follow up?')+`<p>Choose a date to remind the team to check this request.</p><label>Follow-up date<input type="date" id="followdate" min="${dayKey(demoClock)}" value="${r.followupDate&&r.followupDate>=dayKey(demoClock)?r.followupDate:addDays(3)}"></label><div class="actions">${btn('Save follow-up date','saveFollowDate()','primary')}${btn('Remove reminder','removeFollowDate()')}</div><p id="followerror" role="alert" class="danger"></p>`);};
function saveFollowDate(){const v=$('#followdate').value;if(!v||v<dayKey(demoClock)){$('#followerror').textContent='Choose today or a later date.';return;}rec().followupDate=v;rec().followup=true;log(rec(),'Follow-up scheduled for '+dateText(v)+'.');closeModal();render();notify('Follow-up date saved.');}function removeFollowDate(){rec().followupDate=null;rec().followup=false;log(rec(),'Follow-up reminder removed.');closeModal();render();}
statusDialog=function(){baseStatusDialog();Array.from($('#newstatus').options).forEach(o=>o.textContent=statusName(o.value));$('#reason').placeholder='For example: payment confirmed by the department on 6 Oct.';const label=document.createElement('label');label.innerHTML=`Payment date (needed only for Paid)<input type="date" id="paymentdate" max="${dayKey(demoClock)}" value="${rec().paidAt||dayKey(demoClock)}">`;$('#reason').parentElement.after(label);};
saveStatus=function(){const r=rec(),s=$('#newstatus').value,p=$('#paymentdate').value;if(s==='Paid'&&(!p||p>dayKey(demoClock)||p<dayKey(r.submittedAt))){$('#statuserror').textContent='Payment must be on or after receipt and no later than the demo date.';return;}if(!$('#reason').value.trim()){baseSaveStatus();return;}baseSaveStatus();if(s==='Paid')r.paidAt=p;else r.paidAt=null;if(['Paid','Denied'].includes(s))r.followupDate=null;render();};
exportCsv=function(){const cell=v=>'"'+String(v??'').replace(/"/g,'""')+'"';const rows=[['Reference','Client','Claimed','Approved','Status','Received (Asia/Manila)','Last updated (Asia/Manila)','Sent (Asia/Manila)','Last reply (Asia/Manila)','Follow-up date','Payment date'],...records.map(r=>[r.id,r.name,r.amount,r.approved,statusName(r.status),timeText(r.submittedAt),timeText(r.updatedAt),r.sentAt?timeText(r.sentAt):'',r.replyAt?timeText(r.replyAt):'',r.followupDate||'',r.paidAt||''])];const u=URL.createObjectURL(new Blob(['\ufeff'+rows.map(a=>a.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download='RMC2-demo-with-dates.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);notify('Downloaded the demo records with dates.');};
render=function(){baseRender();const labels={'Dashboard':'Home','Reimbursements':'All requests','Email Center':'Emails','Requirements Checker':'Missing documents','Auto-Updater':'Reply updates','Reports':'Reports','Settings':'Settings'};const navbutton=n=>`<button class="${page===n?'active':''}" onclick="go('${n}')" ${page===n?'aria-current="page"':''}>${labels[n]}</button>`;$('#nav').innerHTML=['Dashboard','Reimbursements','Email Center'].map(navbutton).join('')+`<details ${['Requirements Checker','Auto-Updater','Reports','Settings'].includes(page)?'open':''}><summary>More tools</summary>${['Requirements Checker','Auto-Updater','Reports','Settings'].map(navbutton).join('')}</details>`;$('#breadcrumb').textContent=current?'All requests / '+current:(labels[page]||page);if(page==='Requirements Checker'){$('h1').textContent='Missing or unchecked documents';}if(page==='Auto-Updater'){$('h1').textContent='Reply updates';}if(page==='Form'){$('h1').textContent='Add a sample request';}if(page==='Email Center'){$('h1').textContent='Emails';}if(page==='Dashboard')$('#breadcrumb').textContent='Home';};
$('#reset').onclick=()=>modal(modalHead('Start the demo again?')+'<p>This restores the sample requests and clears your practice changes.</p>'+btn('Reset sample data',"seed();current=null;page='Dashboard';closeModal();render();notify('Sample data restored.')",'primary'));
const previousCheckInline=checkInline;
checkInline=function(i){previousCheckInline(i);const r=rec();if(r.status==='Lacking'&&r.docs.every(d=>d.reviewed&&!d.replace)){r.status=r.sentAt?'Processing':'New request';log(r,'All replacement documents have been checked.');render();}};
requirements=function(){return heading('Missing or unchecked documents','Open a request to see which files still need checking.')+`<section class="panel flush">${table(records.filter(r=>!['Paid','Denied'].includes(r.status)&&r.docs.some(d=>!d.reviewed||d.replace)))}</section>`;};
render();
